from qa import *
from playwright.sync_api import sync_playwright
e = Ev("CP-06"); e.w("CP-06", time.strftime("%Y-%m-%d %H:%M"))
TADM = login("admin"); ID = {u: IDS[u] for u in ["qa_rol01","qa_eliminar"]}; e.w("ids",ID)
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(); pg.set_viewport_size({"width":1500,"height":1100})
    pg.goto(WEB+"/login"); pg.get_by_label("Nombre de usuario").fill("admin"); pg.get_by_label("Contraseña").fill(PW["admin"]); pg.get_by_role("button",name="Entrar").click(); pg.wait_for_url("**/home",timeout=15000)
    e.step(1,"listado UI vs BD"); pg.goto(WEB+"/usuarios"); pg.wait_for_timeout(3000); pg.screenshot(path=os.path.join(EVD,"CP-06_paso1_listado.png"))
    e.w("texto del pie de tabla:", pg.locator("text=/\d+[-–]\d+ de \d+|of \d+/").all_inner_texts())
    e.w("filas visibles:", pg.locator("tbody tr").count()); e.w(sql("select count(*) from usuarios"))
    r=api("GET","/usuarios",token=TADM); lst=r.json(); e.w("GET /usuarios",f"HTTP {r.status_code} filas={len(lst)} campos={sorted(lst[0].keys())}","| contiene contraseña/hash:", any(('contrasena' in k or 'hash' in k or 'password' in k) for k in lst[0]))
    e.step(2,"UI editar qa_rol01: correo y rol médico")
    pg.goto(WEB+f"/usuarios/{ID['qa_rol01']}/editar"); pg.wait_for_timeout(2500)
    pg.fill("input[name=correo]","qa_rol01.nuevo@example.com")
    pg.locator("[name=rol_id]").locator("xpath=..").click(); pg.get_by_role("option",name="medico").click()
    pg.screenshot(path=os.path.join(EVD,"CP-06_paso2_form.png"))
    pg.on("response", lambda r: e.w("  respuesta UI:",r.status,r.request.method,r.url,r.text()[:200]) if r.request.method in("PUT","DELETE") else None)
    pg.get_by_role("button",name="Actualizar Información").click(); pg.wait_for_timeout(3000); e.w("toasts:",pg.locator("[data-sonner-toast]").all_inner_texts())
    e.w(sql("select u.nombre_usuario,u.correo,r.nombre rol from usuarios u join usuario_roles ur on ur.usuario_id=u.id join roles r on r.id=ur.rol_id where u.id="+ID['qa_rol01']))
    e.step(3,"login qa_rol01, token y menú"); 
    t=login("qa_rol01","Cuidarte#Aux2026"); e.w("payload:",jwt(t) if t else "login falló")
    pg2=b.new_page(); pg2.goto(WEB+"/login"); pg2.get_by_label("Nombre de usuario").fill("qa_rol01"); pg2.get_by_label("Contraseña").fill("Cuidarte#Aux2026"); pg2.get_by_role("button",name="Entrar").click(); pg2.wait_for_url("**/home",timeout=15000); pg2.wait_for_timeout(1500)
    e.w("menú:",pg2.get_by_role("navigation",name="Navegación principal").inner_text().replace("\n"," | ")); pg2.screenshot(path=os.path.join(EVD,"CP-06_paso3_menu_qa_rol01.png"))
    e.step(4,"PUT rol_id 999"); r=api("PUT",f"/usuarios/{ID['qa_rol01']}",token=TADM,body={"rol_id":999}); e.w(short(r,300))
    e.w(sql("select ur.* from usuario_roles ur where usuario_id="+ID['qa_rol01']))
    e.step(5,"UI eliminar qa_eliminar"); pg.goto(WEB+"/usuarios"); pg.wait_for_timeout(3000)
    row=pg.locator("tr",has_text="qa_eliminar").first; e.w("filas con qa_eliminar:",pg.locator("tr",has_text="qa_eliminar").count())
    row.get_by_role("button",name="Eliminar usuario").click(); pg.wait_for_timeout(800); e.w("diálogo:",pg.get_by_role("dialog").inner_text().replace("\n"," | ")); pg.screenshot(path=os.path.join(EVD,"CP-06_paso5_dialogo.png"))
    pg.get_by_test_id("button-usuario-eliminar-confirmar").click(); pg.wait_for_timeout(3000); e.w("toasts:",pg.locator("[data-sonner-toast]").all_inner_texts())
    e.w(sql("select count(*) from usuarios where nombre_usuario='qa_eliminar'")); r=api("POST","/autenticacion/login",body={"nombre_usuario":"qa_eliminar","password":"Cuidarte#Aux2026"}); e.w("login qa_eliminar:",short(r))
    b.close()
e.step(6,"auditoría"); e.w(sql("select id,usuario_id,accion from auditoria where accion ilike 'USUARIOS_ACTUALIZAR%' or accion ilike 'USUARIOS_ELIMINAR%' order by id"))
